insert into public.content_library (
  id, type, title, content_data, benefit_tag, science_ref, method_tags,
  goal_categories, personalization_variables, intensity, time_of_day_affinity,
  duration_seconds, is_premium
) values
  ('lib_aff_001', 'affirmation', 'Your first line of the day', '{"affirmation":"I am {{future_identity}}.","text":"Say it before you look at your phone. Out loud if you can.","music_bed":"ambient_sunrise"}'::jsonb, 'Rewires self-image', 'Self-affirmation research (Cascio et al., 2016)', array['self_affirmation', 'psycho_cybernetics_self_image']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}']::text[], 'gentle', 'morning', 20, false),
  ('lib_aff_002', 'affirmation', 'Three things, before anything else', '{"affirmation":"I''m grateful for {{gratitude_1}}, {{gratitude_2}}, and {{gratitude_3}}.","text":"Name them slowly. Let each one land before moving to the next.","music_bed":"ambient_warm"}'::jsonb, 'Activates reward circuitry', 'Gratitude and reward pathways (Zahn et al., 2008)', array['gratitude_neuroscience']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{gratitude_1}}', '{{gratitude_2}}', '{{gratitude_3}}']::text[], 'gentle', 'morning', 30, false),
  ('lib_aff_003', 'affirmation', 'Not a task — a description', '{"affirmation":"Every day I {{daily_habit}}, because that''s who I am.","text":"You''re not trying to do this. You''re someone who does this.","music_bed":"ambient_focus"}'::jsonb, 'Strengthens daily habits', 'Identity-based habits (Clear, 2018)', array['identity_based_habits']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{daily_habit}}']::text[], 'moderate', 'morning', 20, false),
  ('lib_img_001', 'image', 'The person who already did it', '{"text":"I am {{future_identity}}","image_prompt":"cinematic portrait of {{user_likeness}} standing in early morning light, calm and certain, {{visual_mood}} grading, shallow depth of field","prompt":"Hold this image for ten seconds before you scroll."}'::jsonb, 'Rewires self-image', 'Self-image research (Maltz, 1960)', array['psycho_cybernetics_self_image']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'moderate', 'morning', null, false),
  ('lib_img_002', 'image', 'Your trigger, written down', '{"text":"If it is {{if_time}}, then I will {{then_action}}.","image_prompt":"minimal typographic card, soft gradient background, single line of text, {{visual_mood}} grading","prompt":"Read it once. That''s the whole practice."}'::jsonb, 'Strengthens implementation intentions', 'If-then planning (Gollwitzer, 1999 — 94 studies, d = .65)', array['implementation_intentions']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{if_time}}', '{{then_action}}', '{{visual_mood}}']::text[], 'gentle', 'morning', null, false),
  ('lib_car_001', 'carousel', 'The first ten minutes decide the day', '{"slides":[{"text":"The first ten minutes of your day set the frame for the other fourteen hours."},{"text":"Not because of productivity. Because of self-perception."},{"text":"Whatever you do first is evidence. Your brain reads it as a statement about who you are."},{"text":"So make the first thing small and unmistakable: {{first_step}}."},{"text":"Do that, and by 9am you already have proof. Today, you''re {{future_identity}}."}],"prompt":"What''s your first ten minutes tomorrow?"}'::jsonb, 'Strengthens daily habits', 'Cue-routine-reward habit formation (Duhigg, 2012)', array['habit_loop', 'identity_based_habits']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{first_step}}', '{{future_identity}}']::text[], 'moderate', 'morning', null, false),
  ('lib_med_001', 'meditation', 'Morning identity primer', '{"text":"Two minutes. Eyes closed. Before the day gets loud.","sections":["induction","identity_visualization","integration"],"music_bed":"alpha_10hz_sunrise"}'::jsonb, 'Primes subconscious mind', 'Alpha-state entrainment (Wahbeh et al., 2007)', array['silva_mirror_of_mind', 'mental_rehearsal']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array[]::text[], 'gentle', 'morning', 120, false),
  ('lib_car_002', 'carousel', 'Why gratitude goes first', '{"slides":[{"text":"Gratitude isn''t a nice-to-have. It''s a state change."},{"text":"Naming something specific you''re grateful for shifts activity in the brain''s reward pathways."},{"text":"That matters because you can''t build a new self-image from a scarcity state."},{"text":"So start here: {{gratitude_self}}. That''s yours. Nobody gave it to you."},{"text":"Now the rest of the work has somewhere solid to stand."}]}'::jsonb, 'Activates reward circuitry', 'Gratitude interventions (Emmons & McCullough, 2003)', array['gratitude_neuroscience']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{gratitude_self}}']::text[], 'gentle', 'morning', null, false),
  ('lib_aff_004', 'affirmation', 'The part of you that''s already working', '{"affirmation":"{{gratitude_self}} — and that''s not an accident.","text":"You built that. Which means you can build the next thing too.","music_bed":"ambient_warm"}'::jsonb, 'Builds self-efficacy', 'Mastery experiences and self-efficacy (Bandura, 1997)', array['self_efficacy']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{gratitude_self}}']::text[], 'gentle', 'morning', 20, false),
  ('lib_vid_001', 'video', 'Your morning, as that person', '{"text":"{{ideal_routine}}","image_prompt":"warm cinematic morning routine, {{user_likeness}} moving with unhurried purpose, {{visual_mood}} grading","prompt":"Watch it like it already happened."}'::jsonb, 'Activates mental rehearsal', 'Mental practice produces cortical change (Pascual-Leone et al., 1995)', array['mental_rehearsal', 'psycho_cybernetics_theater_of_mind']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{ideal_routine}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'moderate', 'morning', 30, false),
  ('lib_car_003', 'carousel', 'Rewriting your self-image', '{"slides":[{"text":"Your self-image is a mental blueprint. It decides what feels possible before you consciously decide anything."},{"text":"It was built from old experiences — most of them from a version of you that no longer exists."},{"text":"You will never outperform it. Not with willpower, not with a better plan."},{"text":"But it isn''t fixed. The brain rebuilds the map it uses most."},{"text":"So use this one: {{future_identity}}."},{"text":"Read it daily until it stops sounding like a stretch and starts sounding like a fact."}]}'::jsonb, 'Rewires self-image', 'Self-image research (Maltz, 1960); neuroplasticity (Doidge, 2007)', array['psycho_cybernetics_self_image']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}']::text[], 'moderate', 'any', null, false),
  ('lib_car_004', 'carousel', 'The sentence you keep repeating', '{"slides":[{"text":"There''s a line running in the background of your head. Yours sounds like this:"},{"text":"\"{{limiting_belief}}\""},{"text":"It feels like an observation. It''s a habit — a thought you''ve rehearsed so many times it became automatic."},{"text":"Rehearsed thoughts strengthen the pathways that carry them. That''s all it is: repetition, not truth."},{"text":"So rehearse the accurate one instead: I am {{future_identity}}, and I have the evidence to prove it."},{"text":"Say the new line today, every time the old one shows up. That''s the whole rewrite."}],"prompt":"Catch the old line once today. Replace it on the spot."}'::jsonb, 'Reframes limiting beliefs', 'Cognitive reframing and neural pathway strengthening', array['psycho_cybernetics_self_image', 'self_affirmation']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}', '{{limiting_belief}}']::text[], 'intense', 'midday', null, false),
  ('lib_img_003', 'image', 'One scene from the life', '{"text":"{{dream_scene}}","image_prompt":"{{dream_scene}}, featuring {{user_likeness}}, {{visual_mood}} grading, cinematic composition, natural light","prompt":"Add one sense the picture doesn''t have. What do you hear?"}'::jsonb, 'Activates mental rehearsal', 'Functional equivalence of mental and physical practice (Pascual-Leone et al., 1995)', array['mental_rehearsal', 'silva_mirror_of_mind']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{dream_scene}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'intense', 'midday', null, false),
  ('lib_med_002', 'meditation', 'The screen and the frame', '{"text":"Five minutes. Somewhere you won''t be interrupted.","sections":["induction","identity_visualization","mental_contrasting","integration"],"music_bed":"alpha_10hz_ambient"}'::jsonb, 'Primes subconscious mind', 'Alpha-state visualization; mental contrasting (Oettingen, 2012)', array['silva_mirror_of_mind', 'woop_mental_contrasting']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array[]::text[], 'moderate', 'midday', 300, false),
  ('lib_car_005', 'carousel', 'The obstacle is the plan', '{"slides":[{"text":"Pure positive visualization makes you feel better and do less. That''s a measured effect, not a moral."},{"text":"Dreaming alone drops the body''s energy for the work. Your brain treats the image as partial credit."},{"text":"What restores it is contrast: the dream, then the honest obstacle, back to back."},{"text":"Yours: {{inner_obstacle}}. And out in the world: {{external_obstacle}}."},{"text":"Now the plan has something to grip. If it is {{if_time}}, then I will {{then_action}}."},{"text":"That''s not pessimism. That''s what turns a wish into an intention."}]}'::jsonb, 'Deepens identity shift', 'Mental contrasting with implementation intentions (Oettingen, 2012)', array['woop_mental_contrasting', 'implementation_intentions']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{external_obstacle}}', '{{if_time}}', '{{inner_obstacle}}', '{{then_action}}']::text[], 'intense', 'midday', null, false),
  ('lib_vid_002', 'video', 'Inside the moment', '{"text":"{{dream_scene}}","image_prompt":"{{dream_scene}}, {{user_likeness}} at the centre, {{visual_mood}} grading, slow push-in, volumetric light","prompt":"Feel it in the body, not just the eyes."}'::jsonb, 'Activates mental rehearsal', 'Mental rehearsal and cortical mapping (Pascual-Leone et al., 1995)', array['mental_rehearsal', 'psycho_cybernetics_theater_of_mind']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{dream_scene}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'intense', 'midday', 45, false),
  ('lib_img_004', 'image', 'Cue. Routine. Reward.', '{"text":"{{if_time}} → {{then_action}} → the version of you that did it","image_prompt":"clean minimal three-part diagram, soft gradient, {{visual_mood}} grading","prompt":"The cue does the work. Make it impossible to miss."}'::jsonb, 'Strengthens daily habits', 'Habit loop (Duhigg, 2012)', array['habit_loop', 'implementation_intentions']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{if_time}}', '{{then_action}}', '{{visual_mood}}']::text[], 'moderate', 'midday', null, false),
  ('lib_aff_005', 'affirmation', 'It shows up. You move anyway.', '{"affirmation":"{{inner_obstacle}} shows up. I move anyway — that''s the whole difference.","text":"The feeling doesn''t have to leave before you start.","music_bed":"ambient_focus"}'::jsonb, 'Reframes limiting beliefs', 'Mental contrasting (Oettingen, 2012)', array['woop_mental_contrasting', 'self_efficacy']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{inner_obstacle}}']::text[], 'moderate', 'midday', 20, false),
  ('lib_car_006', 'carousel', 'Make it embarrassingly small', '{"slides":[{"text":"Confidence isn''t a feeling you find. It''s a residue left behind by evidence."},{"text":"The fastest way to make evidence is to shrink the task until failing is implausible."},{"text":"Yours is already the right size: {{first_step}}."},{"text":"Do it badly. Do it in two minutes. The point is the record, not the result."},{"text":"Repeat that enough times and the belief updates on its own. You won''t have to argue with it."}],"prompt":"Do the two-minute version now, before you scroll on."}'::jsonb, 'Builds self-efficacy', 'Mastery experiences (Bandura, 1997)', array['self_efficacy', 'identity_based_habits']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{first_step}}']::text[], 'gentle', 'midday', null, false),
  ('lib_img_005', 'image', 'Calm under pressure', '{"text":"The person who does {{occupation}} like it''s obvious.","image_prompt":"{{user_likeness}} working with quiet authority in a {{occupation}} setting, {{visual_mood}} grading, natural light","prompt":"Same room, same work — different person doing it."}'::jsonb, 'Rewires self-image', 'Self-image research (Maltz, 1960)', array['psycho_cybernetics_self_image', 'mental_rehearsal']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{occupation}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'moderate', 'midday', null, false),
  ('lib_car_007', 'carousel', 'What imagining does to the brain', '{"slides":[{"text":"Two groups learned the same five-finger piano sequence over five days."},{"text":"One group played it. The other only imagined playing it — no keys, no movement."},{"text":"Brain mapping showed the same region reorganize in both groups."},{"text":"Imagined practice built real motor cortex change. Not as a metaphor — as a measurement."},{"text":"Which is why the minutes you spend inside {{dream_scene}} are not time off. They''re reps."}]}'::jsonb, 'Builds neural pathways', 'Pascual-Leone et al., 1995', array['mental_rehearsal']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{dream_scene}}']::text[], 'moderate', 'midday', null, false),
  ('lib_med_003', 'meditation', 'Rehearsal: the habit, done', '{"text":"Five minutes of practising the thing before you do it.","sections":["induction","action_rehearsal","integration"],"music_bed":"alpha_10hz_focus"}'::jsonb, 'Strengthens daily habits', 'Mental rehearsal (Pascual-Leone et al., 1995); identity-based habits (Clear, 2018)', array['mental_rehearsal', 'identity_based_habits', 'implementation_intentions']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array[]::text[], 'moderate', 'midday', 300, false),
  ('lib_aff_006', 'affirmation', 'Today counted', '{"affirmation":"Today I voted for {{future_identity}}.","text":"Not perfectly. That was never the requirement.","music_bed":"ambient_dusk"}'::jsonb, 'Deepens identity shift', 'Identity-based habits (Clear, 2018)', array['identity_based_habits', 'self_affirmation']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}']::text[], 'gentle', 'evening', 20, false),
  ('lib_car_008', 'carousel', 'Replay the day — but edit it', '{"slides":[{"text":"Pick one moment from today that didn''t go how you wanted."},{"text":"Watch it back once, plainly. No commentary, no verdict on yourself."},{"text":"Now run it again — this time as {{future_identity}} would have handled it."},{"text":"Same room, same people. Different posture, different sentence, different pause before answering."},{"text":"Run the second version twice more. That''s the one your brain keeps."},{"text":"You just rehearsed for the next time it happens. And there will be a next time."}],"prompt":"Which moment did you re-run?"}'::jsonb, 'Rewires self-image', 'Mental rehearsal (Maltz, 1960; Pascual-Leone et al., 1995)', array['psycho_cybernetics_theater_of_mind', 'mental_rehearsal']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}']::text[], 'moderate', 'evening', null, false),
  ('lib_med_004', 'meditation', 'The full session', '{"text":"Ten minutes. The whole arc — settle, appreciate, see it, face it, rehearse it, return.","sections":["induction","gratitude_priming","identity_visualization","mental_contrasting","action_rehearsal","integration"],"music_bed":"alpha_10hz_deep"}'::jsonb, 'Deepens identity shift', 'Alpha-state visualization; mental contrasting (Oettingen, 2012); implementation intentions (Gollwitzer, 1999)', array['silva_mirror_of_mind', 'gratitude_neuroscience', 'woop_mental_contrasting', 'implementation_intentions', 'identity_based_habits']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array[]::text[], 'intense', 'evening', 600, true),
  ('lib_img_006', 'image', 'Still true tonight', '{"text":"{{gratitude_1}}","image_prompt":"quiet evening scene, warm low light, soft focus, {{visual_mood}} grading","prompt":"It was true this morning. It''s still true now."}'::jsonb, 'Activates reward circuitry', 'Gratitude and reward pathways (Zahn et al., 2008)', array['gratitude_neuroscience']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{gratitude_1}}', '{{visual_mood}}']::text[], 'gentle', 'evening', null, false),
  ('lib_car_009', 'carousel', 'What did today prove?', '{"slides":[{"text":"Not \"was today good.\" That''s a mood report, and moods are unreliable witnesses."},{"text":"Ask instead: what did today prove about who I''m becoming?"},{"text":"One kept promise is evidence. One recovery after skipping is stronger evidence."},{"text":"You did {{daily_habit}} — or you didn''t, and you''re still here reading this. Both count for something."},{"text":"Write down the single piece of evidence today produced. Tomorrow starts from there."}],"prompt":"One line. What did today prove?"}'::jsonb, 'Builds self-efficacy', 'Mastery experiences (Bandura, 1997)', array['self_efficacy', 'identity_based_habits']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{daily_habit}}']::text[], 'gentle', 'evening', null, false),
  ('lib_med_005', 'meditation', 'Wind-down gratitude', '{"text":"Two minutes to close the day somewhere other than your inbox.","sections":["induction","gratitude_priming","integration"],"music_bed":"alpha_10hz_night"}'::jsonb, 'Activates reward circuitry', 'Gratitude interventions (Emmons & McCullough, 2003)', array['gratitude_neuroscience']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array[]::text[], 'gentle', 'evening', 120, false),
  ('lib_aff_007', 'affirmation', 'Set for tomorrow', '{"affirmation":"Tomorrow at {{if_time}}, I {{then_action}}.","text":"Decide it now, while it costs nothing. Tomorrow-you just executes.","music_bed":"ambient_dusk"}'::jsonb, 'Strengthens implementation intentions', 'Precommitment (Rogers et al., 2015); if-then plans (Gollwitzer, 1999)', array['implementation_intentions']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{if_time}}', '{{then_action}}']::text[], 'moderate', 'evening', 20, false),
  ('lib_vid_003', 'video', 'Tomorrow morning, seen tonight', '{"text":"{{if_time}} — {{then_action}}","image_prompt":"first light through a window, {{user_likeness}} beginning the day with quiet intent, {{visual_mood}} grading","prompt":"Watch tomorrow before it happens. Then let it go."}'::jsonb, 'Activates mental rehearsal', 'Mental rehearsal (Pascual-Leone et al., 1995)', array['mental_rehearsal', 'implementation_intentions']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{if_time}}', '{{then_action}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'gentle', 'evening', 30, false),
  ('lib_car_010', 'carousel', 'A thermostat, not a thermometer', '{"slides":[{"text":"A thermometer reports the temperature. A thermostat decides it."},{"text":"Your self-image is a thermostat. It has a setting, and it defends that setting."},{"text":"Go too far above it and you''ll self-correct — you''ll call it bad luck, or bad timing, or getting ahead of yourself."},{"text":"Which is why raising the setting matters more than pushing harder against it."},{"text":"The new setting: {{future_identity}}."},{"text":"Set it, then let your behaviour drift up to meet it. That direction is the easy one."}]}'::jsonb, 'Rewires self-image', 'Self-image and the servo-mechanism model (Maltz, 1960)', array['psycho_cybernetics_self_image']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}']::text[], 'moderate', 'any', null, false),
  ('lib_aff_008', 'affirmation', 'Ready is not the requirement', '{"affirmation":"I don''t have to feel ready. I have to be the person who starts.","text":"Motivation follows action far more reliably than it leads it.","music_bed":"ambient_focus"}'::jsonb, 'Builds self-efficacy', 'Self-efficacy through action (Bandura, 1997)', array['self_efficacy', 'identity_based_habits']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array[]::text[], 'moderate', 'any', 20, false),
  ('lib_img_007', 'image', 'The old line, struck through', '{"text":"{{limiting_belief}}","image_prompt":"typographic composition, one sentence struck through, replacement line beneath in clear type, {{visual_mood}} grading","prompt":"Underneath it: I am {{future_identity}}."}'::jsonb, 'Reframes limiting beliefs', 'Cognitive reframing; self-affirmation (Cascio et al., 2016)', array['self_affirmation', 'psycho_cybernetics_self_image']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{future_identity}}', '{{limiting_belief}}', '{{visual_mood}}']::text[], 'intense', 'any', null, false),
  ('lib_med_006', 'meditation', 'Meeting the version of you that made it', '{"text":"Five minutes with the person on the other side of {{timeline}}.","sections":["induction","identity_visualization","action_rehearsal","integration"],"music_bed":"alpha_10hz_ambient"}'::jsonb, 'Deepens identity shift', 'Mental rehearsal (Maltz, 1960); future self-continuity research', array['psycho_cybernetics_theater_of_mind', 'mental_rehearsal', 'identity_based_habits']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{timeline}}']::text[], 'moderate', 'any', 300, false),
  ('lib_car_011', 'carousel', 'Every action is a vote', '{"slides":[{"text":"Goals are a direction. They''re bad at deciding what you do on a Tuesday you didn''t sleep well."},{"text":"Identity decides that. Not \"I want to run\" — \"I''m a runner, and runners run on bad days too.\""},{"text":"Each small action is a vote for a type of person. Nothing needs a unanimous result."},{"text":"You just need the majority. Miss once and the count still holds."},{"text":"Today''s vote: {{daily_habit}}. Cast it, and the identity does the arguing for you."}]}'::jsonb, 'Deepens identity shift', 'Identity-based habits (Clear, 2018)', array['identity_based_habits', 'habit_loop']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{daily_habit}}']::text[], 'moderate', 'any', null, false),
  ('lib_vid_004', 'video', 'Sixty seconds inside it', '{"text":"{{dream_description}}","image_prompt":"extended cinematic sequence of {{dream_description}}, {{user_likeness}} present throughout, {{visual_mood}} grading","prompt":"Nothing to do here but be in it."}'::jsonb, 'Activates mental rehearsal', 'Functional equivalence of imagined practice (Pascual-Leone et al., 1995)', array['mental_rehearsal', 'silva_mirror_of_mind']::text[], array['career_money', 'health_fitness', 'love_relationships', 'creative_purpose']::text[], array['{{dream_description}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'intense', 'any', 60, false),
  ('lib_aff_009', 'affirmation', 'The byproduct', '{"affirmation":"I don''t chase the money. I become the person it follows.","text":"Skill, judgment, and showing up are the assets. The number is downstream.","music_bed":"ambient_focus"}'::jsonb, 'Rewires self-image', 'Identity-based habits (Clear, 2018)', array['identity_based_habits', 'psycho_cybernetics_self_image']::text[], array['career_money']::text[], array[]::text[], 'moderate', 'any', 20, false),
  ('lib_aff_010', 'affirmation', 'Not for a body', '{"affirmation":"I don''t train for a body. I train because I''m someone who trains.","text":"The result is a side effect. The identity is the point.","music_bed":"ambient_drive"}'::jsonb, 'Strengthens daily habits', 'Identity-based habits (Clear, 2018)', array['identity_based_habits']::text[], array['health_fitness']::text[], array[]::text[], 'moderate', 'any', 20, false),
  ('lib_img_008', 'image', 'The way you show up for people', '{"text":"I am {{future_identity}} — including with the people I love.","image_prompt":"warm intimate scene, {{user_likeness}} fully present with another person, soft natural light, {{visual_mood}} grading","prompt":"Identity isn''t only what you achieve. It''s how you arrive."}'::jsonb, 'Deepens identity shift', 'Self-affirmation and core values (Cascio et al., 2016)', array['self_affirmation', 'psycho_cybernetics_self_image']::text[], array['love_relationships']::text[], array['{{future_identity}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'gentle', 'any', null, false),
  ('lib_img_009', 'image', 'The work gets made by whoever shows up', '{"text":"{{daily_habit}} — on the good days and the flat ones.","image_prompt":"creative workspace mid-project, {{user_likeness}} absorbed in the work, {{visual_mood}} grading","prompt":"Nobody sees the flat days in the finished thing."}'::jsonb, 'Strengthens daily habits', 'Habit loop (Duhigg, 2012); identity-based habits (Clear, 2018)', array['habit_loop', 'identity_based_habits']::text[], array['creative_purpose']::text[], array['{{daily_habit}}', '{{user_likeness}}', '{{visual_mood}}']::text[], 'moderate', 'any', null, false)
on conflict (id) do update set
